/**
 * Capture quality of one assessment per step (SRS-QC-010): frames, head angles, alignment, and the capture conditions
 * (tracked share, face position and size, light and its direction, sharpness), with plain warnings above.
 */
import {
  MOVEMENT_TASKS,
  brighterSide,
  conditionNotes,
  type AnalysisResult,
  type MovementTaskId,
  type StepConditions,
  type TaskQuality,
} from '../../core';
import { TASK_SHORT } from '../labels';
import { Notice } from './common';

const pct = (x: number) => `${Math.round(x * 100)}%`;

/** '132 · 오른쪽 15% 밝음 · 위 6% 밝음': mean luminance and the brighter sides (patient's left/right). */
export function lightText(l: NonNullable<StepConditions['light']>): string {
  const h =
    Math.abs(l.horiz) < 0.03 ? '좌우 고름' : `${brighterSide(l.horiz) === 'right' ? '오른쪽' : '왼쪽'} ${pct(Math.abs(l.horiz))} 밝음`;
  const v = Math.abs(l.vert) < 0.03 ? '' : ` · ${l.vert > 0 ? '위' : '아래'} ${pct(Math.abs(l.vert))} 밝음`;
  return `${Math.round(l.mean)} · ${h}${v}`;
}

export const stepLabel = (s: string): string => (s === 'rest' ? '안정' : (TASK_SHORT[s as MovementTaskId] ?? s));

export function CaptureQuality({ a }: { a: AnalysisResult }) {
  const rows: [string, TaskQuality][] = [
    ...(a.restQuality ? [['안정', a.restQuality] as [string, TaskQuality]] : []),
    ...MOVEMENT_TASKS.flatMap((t) => (a.tasks[t] ? [[TASK_SHORT[t], a.tasks[t]!.quality] as [string, TaskQuality]] : [])),
  ];
  const notes = conditionNotes(a, stepLabel);
  const anyConditions = rows.some(([, q]) => q.conditions);
  return (
    <>
      {notes.length > 0 && (
        <div class="stack" style={{ gap: '6px' }}>
          {notes.map((n) => (
            <Notice tone="warn">
              <span class="small">{n}</span>
            </Notice>
          ))}
        </div>
      )}
      <div class="stack" style={{ gap: '8px' }}>
        {rows.map(([label, q]) => {
          const c = q.conditions;
          const parts = c
            ? [
                `점 추적 ${c.trackKept !== undefined ? pct(c.trackKept) : '–'}`,
                `가운데서 ${pct(Math.hypot(c.offsetX, c.offsetY))}`,
                `얼굴 폭 ${pct(c.faceWidth)}`,
                `눈 사이 ${Math.round(c.eyePx)}px`,
                `빛 ${c.light ? lightText(c.light) : '–'}`,
                `선명도 ${c.sharp !== undefined ? `${c.sharp.toFixed(2)} · 잡음 ${(c.noise ?? 0).toFixed(1)}` : '–'}`,
              ]
            : [];
          return (
            <div class="small">
              <b>{label}</b>{' '}
              <span class="ink2">
                프레임 {q.framesUsed}/{q.framesValid}/{q.framesTotal} · 좌우 {q.medianAbsYaw.toFixed(1)}° · 상하{' '}
                {q.medianAbsPitch.toFixed(1)}° · 기울기 {q.medianAbsRoll.toFixed(1)}° · 정렬{' '}
                {Number.isFinite(q.alignmentResidual) ? q.alignmentResidual.toFixed(3) : '–'}
              </span>
              {parts.length > 0 && <div class="xsmall ink2">{parts.join(' · ')}</div>}
            </div>
          );
        })}
      </div>
      {!anyConditions && <p class="xsmall muted">촬영 조건(점 추적·위치·빛·선명도)은 2026-10-13 이후의 평가부터 기록됩니다.</p>}
      <p class="xsmall muted">
        프레임 = 사용/유효/전체. 각도는 쓴 프레임의 중앙값입니다. 점 추적 = 얼굴 점 가운데 추적이 유지된 비율(나머지는 검출 위치를 씀). 위치
        = 얼굴 중심이 화면 가운데서 벗어난 정도, 폭 = 관자놀이 사이 거리 / 화면 폭. 빛 = 얼굴 밝기(0–255)와 더 밝은 쪽(환자 기준 좌우,
        위아래). 선명도·잡음은 같은 폰으로 찍은 평가끼리 비교하는 상대값입니다.
      </p>
    </>
  );
}
